import {
  AuthenticationProvider,
  ExternalGroup,
  Group,
  GroupUser,
} from "@server/models";
import { sequelize } from "@server/storage/database";
import { buildUser } from "@server/test/factories";
import groupsSyncer from "./groupsSyncer";

